// Transform events data for HoneyGo pricing
const response = $input.first().json;
const events = response._embedded?.events || [];

const now = new Date();
const threeHoursFromNow = new Date(now.getTime() + 3 * 60 * 60 * 1000);

// Filter events happening soon
const upcomingEvents = events
  .filter(event => {
    const eventDate = new Date(event.dates.start.dateTime);
    return eventDate >= now && eventDate <= threeHoursFromNow;
  })
  .map(event => {
    // Estimate attendance based on venue
    let attendance = 5000;
    let multiplier = 1.2;

    const type = event.classifications?.[0]?.segment?.name?.toLowerCase() || 'other';

    if (type.includes('sport')) {
      attendance = 20000;
      multiplier = 1.4;
    } else if (type.includes('music')) {
      attendance = 15000;
      multiplier = 1.5;
    } else if (type.includes('arts')) {
      attendance = 2000;
      multiplier = 1.15;
    }

    return {
      id: event.id,
      name: event.name,
      type: type,
      venue: event._embedded?.venues?.[0]?.name || 'Unknown',
      date: event.dates.start.localDate,
      time: event.dates.start.localTime,
      expected_attendance: attendance,
      pricing_multiplier: multiplier,
      surge_radius_miles: 3
    };
  });

let finalMultiplier = 1.0;
let reasoning = 'No major events detected nearby';

if (upcomingEvents.length > 0) {
  // Use highest multiplier from nearby events
  finalMultiplier = Math.max(...upcomingEvents.map(e => e.pricing_multiplier));
  reasoning = `${upcomingEvents.length} event(s) nearby: ${upcomingEvents.map(e => e.name).join(', ')}`;
}

return {
  city: $input.first().json.body?.city || 'Unknown',
  events: upcomingEvents,
  event_count: upcomingEvents.length,
  pricing_multiplier: finalMultiplier,
  reasoning: reasoning,
  timestamp: new Date().toISOString()
};
